// ❌ OLD: Before JDK 9, String wrapped a char[]: every character cost
// 2 bytes (UTF-16), even for pure-ASCII text. A 100-character ASCII
// string consumed 200 bytes of backing storage plus object overhead.
public class StringMemoryLegacy {
  // ❌ OLD: 'hello' stored as 5 x 2-byte chars = 10 bytes
  String s = "hello";

  // A JSON-heavy app with millions of short ASCII keys paid double the
  // necessary memory, increasing heap pressure and GC frequency.
}

// ✅ NEW: Compact Strings (JDK 9+) back ASCII/Latin-1 strings with a
// byte[] and a coder flag (LATIN1 = 1 byte/char). 'hello' costs 5
// bytes instead of 10. Multi-byte content uses UTF16 mode automatically.
public class StringMemoryModern {
  String ascii = "hello"; // ✅ NEW: LATIN1 coder, 1 byte/char
  String emoji = "hello 🚀"; // ✅ NEW: UTF16 coder, auto-detected

  // Same public API — length() returns characters; the coder is an
  // internal layout detail. JVM string intrinsics pick fast paths by
  // coder. For GC-time savings on duplicate content, enable:
  //   -XX:+UseStringDeduplication -XX:StringDeduplicationAgeThreshold=3
}
